package com.featuredeliveryintelligence.fdi.runtime;import java.util.*;
public final class StructuralMaintenance{private StructuralMaintenance(){}public static Map<String,Object>deriveSignals(Map<String,Object>d,List<Map<String,Object>>assets,List<String>high,int max){if(!Boolean.TRUE.equals(d.get("non_authoritative"))||high.isEmpty()||max<1)throw new RuntimeContractException("invalid structural maintenance request");Map<String,Map<String,Object>>byId=new TreeMap<>();for(String pair:List.of("ADDED:added","REMOVED:removed")){String[]p=pair.split(":");for(Object raw:RuntimeMaps.list(d,p[1])){Map<String,Object>o=map(raw);if(!Boolean.TRUE.equals(o.get("non_authoritative")))throw new RuntimeContractException("observation must remain non_authoritative");String rel=RuntimeMaps.requiredString(o,"relation_type"),oid=RuntimeMaps.requiredString(o,"observation_id");if(!high.contains(rel))continue;Set<String>repos=repos(o);for(Map<String,Object>a:assets){String aid=RuntimeMaps.requiredString(a,"asset_ref_id");if(!"PUBLISHED".equals(a.get("publication_state"))||!"ACTIVE".equals(a.get("validity_state")))continue;Set<String>assetRepos=strings(RuntimeMaps.list(a,"repository_ids"));Set<String>assetRelations=strings(RuntimeMaps.list(a,"relation_types"));if(Collections.disjoint(repos,assetRepos)||(!assetRelations.isEmpty()&&!assetRelations.contains(rel)))continue;String id="maintenance:"+p[0].toLowerCase()+":"+aid+":"+oid;byId.put(id,Map.of("signal_id",id,"affected_asset_ref_id",aid,"change_kind",p[0],"relation_type",rel,"observation_id",oid,"repository_ids",new TreeSet<>(repos),"proposed_action","REVIEW_REALIZATION","requires_governance_decision",true));}}}List<Map<String,Object>>signals=new ArrayList<>(byId.values());boolean truncated=signals.size()>max;if(truncated)signals=new ArrayList<>(signals.subList(0,max));return Map.of("signals",signals,"diagnostics",List.of(),"truncated",truncated,"incomplete",truncated,"requires_governance",!signals.isEmpty());}private static Set<String>repos(Map<String,Object>o){Set<String>r=new HashSet<>();for(String k:List.of("from","to")){Object n=o.get(k);if(n instanceof Map<?,?>m&&m.get("repository_id")!=null)r.add(String.valueOf(m.get("repository_id")));}return r;}private static Set<String>strings(List<Object>x){Set<String>s=new HashSet<>();for(Object v:x)s.add(String.valueOf(v));return s;}@SuppressWarnings("unchecked")private static Map<String,Object>map(Object x){return(Map<String,Object>)x;}}
